package ama.api;
import ama.storage.*;import ama.transcript.*;import javax.sql.DataSource;import java.util.*;import org.springframework.boot.WebApplicationType;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.context.annotation.*;import org.springframework.context.support.GenericApplicationContext;import org.springframework.context.ConfigurableApplicationContext;import static org.junit.jupiter.api.Assertions.*;
/** Direct production-service diagnosis; finite isolated profiles, no servlet/session/worker/pipeline. */
public final class Task11B3BudgetApi {
 public enum Profile {ORIGINAL_1M(1048576),CONTROL_2M(2097152);public final long archiveTotalBytes;Profile(long bytes){archiveTotalBytes=bytes;}}
 @Configuration(proxyBeanMethods=false) @Import({Task11B3LifecycleApi.Wiring.class,KnowledgeConfiguration.class}) static class Wiring {}
 @org.springframework.boot.test.context.TestConfiguration(proxyBeanMethods=false) @EnableAutoConfiguration(excludeName={"org.springframework.boot.security.autoconfigure.UserDetailsServiceAutoConfiguration","org.springframework.boot.jdbc.autoconfigure.DataSourceAutoConfiguration","org.springframework.boot.flyway.autoconfigure.FlywayAutoConfiguration"}) @Import(Wiring.class) static class Direct {}
 public static Map<String,Object> properties(Task11B3LifecycleApi.Settings settings,Profile profile){assertFalse(settings.unavailableArchive());var values=new HashMap<String,Object>(Task11B3LifecycleApi.properties(settings));assertEquals(1048576L,((Number)values.get("processing.bounds.archive-total-bytes")).longValue());values.put("processing.bounds.archive-total-bytes",profile.archiveTotalBytes);return values;}
 public static ConfigurableApplicationContext start(DataSource source,FileBackendDefinitions definitions,Task11B3LifecycleApi.Settings settings,Profile profile){return new SpringApplicationBuilder(Direct.class).web(WebApplicationType.NONE).properties(properties(settings,profile)).initializers(context->Task11B3LifecycleApi.infrastructure((GenericApplicationContext)context,source,definitions)).run("--spring.main.web-application-type=none","--management.endpoint.health.group.ready.include=ping","--spring.flyway.enabled=false","--spring.sql.init.mode=never","--logging.level.root=ERROR","--logging.level.ama.transcript.JdbcPublicationReplacement=WARN","--logging.level.ama.worker.WorkerLoop=WARN");}
 public static void requireInstalled(ConfigurableApplicationContext app){Task11B3LifecycleApi.requireInstalled(app);assertNull(app.getEnvironment().getProperty("local.server.port"),"Diagnostic has no servlet server");}
}